/**
 *  One transactionally consistent, deterministic projection of a page's
 *  complete current block tree.
 */
export type PageDocumentSnapshot = {
	pageUuid: string,
	revision: DocumentRevision,
	blocks: Block[],
};

export type PageKind = { kind: "note" } | { kind: "journal"; date: JournalDate };

/**
 *  The durable structural layout of a page. Reading is pane-local
 *  presentation state and deliberately does not cross this boundary.
 */
export type PageLayout = "outline" | "document";

/**
 *  A typed projection over the page catalog. Normal note navigation uses
 *  `Notes`; explicit callers may request Journals or the complete catalog.
 */
export type PageListFilter = "notes" | "journals" | "all";

export type PageRenderSnapshot = {
	document: PageDocumentSnapshot,
	images: AttachmentImageDescriptor[],
};

export type SafeAreaInsets = {
	top: number | null,
	right: number | null,
	bottom: number | null,
	left: number | null,
};

export type SearchHit = {
	content: Content,
	score: number | null,
	snippet?: string | null,
};

export type SearchMode = "fts" | "semantic";

export type SearchTokenMode = "plain" | "prefix";

export type SecretKey = "SYNC_TOKEN";

export type SettingsCapabilities = {
	windowDecorations: boolean,
	windowCornerRounding: boolean,
};

export type SettingsSnapshot = {
	capabilities: SettingsCapabilities,
	windowCornerRadius: number,
	windowDecorationMode: WindowDecorationMode,
	activeWindowDecorationMode: WindowDecorationMode,
	windowDecorationsRequireRestart: boolean,
	startupView: StartupView,
	startupPageUuid: string | null,
	syncServerUrl: string | null,
	aiSearchEnabled: boolean,
	aiSearchTrigger: AiSearchTrigger,
	aiSearchRerank: boolean,
	searchDebugSources: boolean,
	configuredKeys: SecretKey[],
	configPath: string,
};

export type SettingsUpdate = {
	windowCornerRadius: number,
	windowDecorationMode: WindowDecorationMode,
	startupView: StartupView,
	startupPageUuid: string | null,
	syncServerUrl: string | null,
	aiSearchEnabled: boolean,
	aiSearchTrigger: AiSearchTrigger,
	aiSearchRerank: boolean,
	searchDebugSources: boolean,
	apiKeys?: Partial<{ [key in SecretKey]: string }>,
	clearKeys?: SecretKey[],
};

export type SourcePosition = {
	/**  One-based physical line number. */
	line: number,
	/**  One-based Unicode scalar column. */
	column: number,
	/**  Zero-based byte offset in the original UTF-8 source. */
	byteOffset: number,
};

export type SourceRange = {
	start: SourcePosition,
	end: SourcePosition,
};

export type StartupErrorEvent = {
	message: string,
};

export type StartupReadyEvent = null;

export type StartupStatus = { state: "starting"; message: string } | { state: "ready" } | { state: "error"; message: string };

export type StartupView = "dashboard" | "last_session" | "today" | "specific_page";

export type StylusAvailability = "available" | "not_detected" | "unknown";

export type SyncConnectionState = "disabled" | "connecting" | "syncing" | "online" | "offline" | "conflict" | "error";

export type SyncStatus = {
	state: SyncConnectionState,
	serverUrl: string | null,
	lastServerSeq: number,
	pendingOperations: number,
	message: string | null,
};

/**  Durable workflow state carried only by a task block. */
export type TaskState = "todo" | "doing" | "now" | "later" | "done" | "waiting" | "cancelled";

export type WindowDecorationMode = "native" | "borderless";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

